import re
def en_of(zh):
    base=re.sub(r'[（(].*','',zh).strip()
    if base in EN: return EN[base]
    m=re.match(r'^(.+?)其他学科$',base)
    if m and m.group(1) in EN: return 'Other '+EN[m.group(1)]
    if base.endswith('其他学科'):
        return 'Other '+base[:-4]
    return None
